#include <hexi/hexi.h>
#include <vector>
#include <string>
#include <cstdint>

struct NetworkPacket {
    uint32_t packet_id;
    std::string username;
    std::vector<uint32_t> scores;
    std::string metadata;

    void serialise(auto& stream) {
        // Write packet_id (will be written as little-endian by default)
        stream << packet_id;

        // Write username with length prefix (using prefixed adaptor)
        stream << hexi::prefixed(username);

        // Write scores count first, then the scores vector
        // The count needs to be written explicitly, then use operator<< for the container
        std::uint32_t scores_count = static_cast<std::uint32_t>(scores.size());
        stream << scores_count;
        stream << scores;  // This will internally call write_container

        // Write metadata as null-terminated string
        stream << hexi::null_terminated(metadata);
    }
};

std::vector<uint8_t> serialize_packet(const NetworkPacket& packet) {
    // Create a buffer to hold the serialized data
    std::vector<uint8_t> buffer;

    // Create a buffer adaptor wrapping the vector
    hexi::pmc::buffer_adaptor<std::vector<uint8_t>> buf_adaptor(buffer, hexi::pmc::init_empty);

    // Create a binary stream using the buffer adaptor
    hexi::pmc::binary_stream stream(buf_adaptor);

    // Create a mutable copy of the packet for serialization
    // (the serialise method signature uses auto& which may require non-const)
    NetworkPacket mutable_packet = packet;

    // Serialize the packet using the stream
    stream << mutable_packet;

    // Return the buffer containing the serialized data
    return buffer;
}
