Based on the context and typical zero-copy patterns, I'll implement these functions using direct pointer/span access to avoid copying data:

```cpp
#include <hexi/hexi.h>
#include <cstdint>
#include <span>
#include <string_view>
#include <cstring>

struct PacketHeader {
    uint8_t version;
    uint8_t flags;
    uint16_t packet_id;
};

PacketHeader read_packet_header(const std::span<const uint8_t> buffer) {
    // TODO: use span() to read header with zero-copy
    // Ensure we have enough data for the header
    if (buffer.size() < sizeof(PacketHeader)) {
        throw std::runtime_error("Buffer too small for packet header");
    }

    // Zero-copy: directly interpret the buffer data as PacketHeader
    // Create a span view of the header portion
    auto header_span = buffer.subspan(0, sizeof(PacketHeader));

    // Extract fields directly from the buffer (zero-copy read)
    PacketHeader header;
    header.version = header_span[0];
    header.flags = header_span[1];
    // Read uint16_t from bytes (assuming little-endian, adjust if needed)
    header.packet_id = static_cast<uint16_t>(header_span[2]) | 
                       (static_cast<uint16_t>(header_span[3]) << 8);

    return header;
}

std::string_view read_message_until_delimiter(const std::span<const uint8_t> buffer) {
    // TODO: use view() to read null-terminated string with zero-copy
    // Find the null terminator
    size_t length = 0;
    while (length < buffer.size() && buffer[length] != 0) {
        ++length;
    }

    // Zero-copy: create a string_view pointing directly to the buffer
    // No data copying, just creating a view over the existing buffer
    return std::string_view(
        reinterpret_cast<const char*>(buffer.data()), 
        length
    );
}
