```cpp
#include <hexi/hexi.h>
#include <vector>
#include <cstdint>

std::vector<uint8_t> read_buffer_data(const std::vector<uint8_t>& source_buffer, size_t bytes_to_read) {
    // Create a mutable copy of the source buffer to work with buffer_adaptor
    std::vector<uint8_t> buffer_copy = source_buffer;

    // Create a buffer_adaptor for the source buffer
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer_copy);

    // Prepare destination buffer
    std::vector<uint8_t> result(bytes_to_read);

    // Read the specified number of bytes from the buffer adaptor
    // Only read up to the available size in the buffer
    size_t bytes_available = adaptor.size();
    size_t bytes_actual = (bytes_to_read < bytes_available) ? bytes_to_read : bytes_available;

    if (bytes_actual > 0) {
        adaptor.read(result.data(), bytes_actual);
        result.resize(bytes_actual);  // Resize if we read less than requested
    } else {
        result.clear();
    }

    return result;
}

void write_buffer_data(std::vector<uint8_t>& dest_buffer, const std::vector<uint8_t>& source_data) {
    // Create a buffer_adaptor for the destination buffer
    // Use init_empty to start with write cursor at position 0
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(dest_buffer, hexi::init_empty);

    // Write the source data to the buffer adaptor
    if (!source_data.empty()) {
        adaptor.write(source_data.data(), source_data.size());
    }
}
