#include <hexi/hexi.h>
#include <cstdint>
#include <span>

struct PacketHeader {
    uint32_t magic;
    uint16_t version;
    uint16_t flags;
};

PacketHeader read_header_with_span(const std::span<const uint8_t> buffer) {
    // Create a mutable vector from the input span to work with buffer_adaptor
    std::vector<uint8_t> buffer_vec(buffer.begin(), buffer.end());

    // Create a buffer_adaptor to manage the buffer
    hexi::buffer_adaptor<std::vector<uint8_t>> adaptor(buffer_vec);

    // Get the read pointer
    const uint8_t* read_pointer = adaptor.read_ptr();

    // Check available data - ensure we have enough bytes for the header
    constexpr std::size_t header_size = sizeof(PacketHeader);
    if (adaptor.size() < header_size) {
        // Not enough data, return a default-initialized header
        return PacketHeader{0, 0, 0};
    }

    // Create a binary_stream for zero-copy operations
    hexi::pmc::buffer pmc_buffer;
    pmc_buffer.resize(buffer.size());
    std::memcpy(pmc_buffer.data(), buffer.data(), buffer.size());

    hexi::binary_stream stream(pmc_buffer);

    // Get a zero-copy view of the header using span
    // Note: We need to get the header as a span of bytes, then interpret it
    constexpr std::size_t header_element_count = header_size;
    auto header_view = stream.span<uint8_t>(header_element_count);

    // Parse the header from the view
    PacketHeader header;
    if (header_view.size() >= header_size) {
        const uint8_t* data = header_view.data();

        // Read magic (uint32_t)
        std::memcpy(&header.magic, data, sizeof(uint32_t));
        data += sizeof(uint32_t);

        // Read version (uint16_t)
        std::memcpy(&header.version, data, sizeof(uint16_t));
        data += sizeof(uint16_t);

        // Read flags (uint16_t)
        std::memcpy(&header.flags, data, sizeof(uint16_t));
    } else {
        // Failed to get proper view
        header = PacketHeader{0, 0, 0};
    }

    return header;
}
