#include <hexi/file_buffer.h>
#include <vector>
#include <cstdint>
#include <filesystem>

std::vector<uint8_t> preview_file_header(const std::filesystem::path& file_path, size_t header_size) {
    // Create a file_buffer object to read from the file
    hexi::file_buffer buffer(file_path);

    // Check if the file was opened successfully
    if (!buffer) {
        return std::vector<uint8_t>();
    }

    // Determine the actual size to read (minimum of requested size and file size)
    size_t actual_size = std::min(header_size, buffer.size());

    // Create a vector to store the header data
    std::vector<uint8_t> header_data(actual_size);

    // Use the copy method to read header data without advancing the read pointer
    buffer.copy(header_data.data(), actual_size);

    // Check if the copy operation was successful
    if (!buffer) {
        return std::vector<uint8_t>();
    }

    return header_data;
}

