	 *  
	 * @return Reference to the current stream.
	 */
	template<is_iterable T>
	binary_stream_reader& operator>>(prefixed<T> adaptor) {
		std::uint32_t count = 0;
		*this >> endian::le(count);
		read_container(adaptor.str, count);
		return *this;
	}

