bool check_regions_overlap(const void* src, std::size_t src_len, const void* dst, std::size_t dst_len) {
    // Convert pointers to uintptr_t for safe arithmetic comparison
    uintptr_t src_start = reinterpret_cast<uintptr_t>(src);
    uintptr_t src_end = src_start + src_len;
    uintptr_t dst_start = reinterpret_cast<uintptr_t>(dst);
    uintptr_t dst_end = dst_start + dst_len;

    // Check for null pointers or zero-length regions
    if (!src || !dst || src_len == 0 || dst_len == 0) {
        return false;
    }

    // Two regions overlap if:
    // - src_start is within [dst_start, dst_end)
    // - OR dst_start is within [src_start, src_end)
    // This can be simplified to: NOT (one region is completely before the other)
    // Regions don't overlap if: src_end <= dst_start OR dst_end <= src_start
    // Therefore, regions overlap if: src_end > dst_start AND dst_end > src_start

    return (src_end > dst_start) && (dst_end > src_start);
}

bool safe_memory_copy(void* destination, const void* source, std::size_t length) {
    // Check for null pointers
    if (!destination || !source) {
