struct MeasurementData {
    uint32_t sensor_id;
    std::vector<float> temperatures;
    double pressure;

    void serialise(auto& adaptor) const {
        // Write sensor_id directly
        adaptor << sensor_id;

        // Write number of temperatures (for deserialization)
        adaptor << static_cast<uint32_t>(temperatures.size());

        // Convert each temperature from native to little-endian and write
        for (const auto& temp : temperatures) {
            float converted = hexi::endian::conditional_reverse(temp, std::endian::native, std::endian::little);
            adaptor.write(&converted, sizeof(float));
        }

        // Convert pressure from native to little-endian and write
        double converted_pressure = hexi::endian::conditional_reverse(pressure, std::endian::native, std::endian::little);
        adaptor.write(&converted_pressure, sizeof(double));
    }

    void serialise(auto& adaptor) {
        // Read sensor_id directly
        adaptor >> sensor_id;

        // Read number of temperatures
        uint32_t temp_count = 0;
        adaptor >> temp_count;

        // Read temperatures and convert from little-endian to native
        temperatures.resize(temp_count);
        for (auto& temp : temperatures) {
            adaptor.read(&temp, sizeof(float));
            hexi::endian::little_to_native_inplace(temp);
        }

        // Read pressure and convert from little-endian to native
        adaptor.read(&pressure, sizeof(double));
        hexi::endian::little_to_native_inplace(pressure);
    }
};

