    // Create a mutable copy for the adaptor
    std::vector<uint8_t> buffer_copy(buffer.begin(), buffer.end());
    hexi::buffer_adaptor adaptor(buffer_copy);
    hexi::binary_stream stream(adaptor);

    MeasurementData data;

    // Use the stream's deserialise method to deserialize the entire structure
    stream.deserialise(data);

    return data;
}

